# Review 128 VPS deployment. Run once in an elevated PowerShell on the VPS.
#   Check only, changes nothing:  powershell -ExecutionPolicy Bypass -File .\Deploy128.ps1 -Check
#   Deploy:                       powershell -ExecutionPolicy Bypass -File .\Deploy128.ps1
# Order is fixed: online backup, Caddy, backend. Caddy must overwrite the client address
# header before a backend that trusts it runs. There is no schema change. Any failed health
# check restores the previous files and config. No credentials are embedded or printed.
param([switch]$Check)
$ErrorActionPreference='Stop'
Set-StrictMode -Version Latest
$files=@(
    @{name='api.py';old='1b8aa4b5b8b42d44a467b9402d683fcfe2e98672eeaff20ea84a163948d50005';new='f7c32772e5b735244ec178ac05ccc514b83e2857042fbd01f763c14c0971ff79';data=''},
    @{name='commerce.py';old='a38d2a4e87199d53253be0df206bcf612698afdefcf9cfc61d169cefd05ce616';new='f0c5185a5ffd9da2a270465d1566a1935e33de93a8e02c23ed3667149fcdedb9';data=''},
    @{name='identity.py';old='e648e08c9e074d7366ce0547480f8ffa0c66306b8bed817ec7ae8cbafba94e40';new='6eecbc26cc378ce32c2ee3923073716e787a220d10e6a7ac65ce9c98cbd14e65';data=''},
    @{name='replay_contract.py';old='ddf09336d8cc79ea82c6ad81bdcc6253e52fb903703d994c0f38564e0cfc44e3';new='951ee27954f7540295e86975de4eba0499504786dbecb331d66eea9912b9d805';data=''},
    @{name='replay_service.py';old='83950fadb376389ac96ffb661615066f0587a919e0f2a8844ff8a4922296ded9';new='2c87bfc79dcc382885bd0465adea2cbc105459a531af43cf644fdf2324bd881d';data=''},
    @{name='service.py';old='80d7aab2561885ce30c2764ab006d5b836fec8423c12ba2f3ec0b406b83cf261';new='4a9b68af2125d68e9ec4746ca928ce6a042849d2ee11d374e73e99a9bd8373f1';data=''},
    @{name='staging_sdk126.py';old='7dbc311e49e45fad62a458db2a72320ebdd5c77df3961ef37eecace04994c442';new='f952fd2ef92b4efecdb6d787cf7ee73c468f9ed1e2ee589784e10be906bf7db0';data=''}
)
$Backend='C:\Apps\HeartOfTheRain\Monetization126\Backend'
$Source=Join-Path $Backend 'hotr_backend'
$Python='C:\Apps\HeartOfTheRain\Backend\.venv-service\Scripts\python.exe'
$Services='C:\ProgramData\HeartOfTheRain\services'
$Manifest=Join-Path $Services 'staging-manifest.json'
$CaddyFile=Join-Path $Services 'Caddyfile'
$CaddyExe='C:\Tools\Caddy\caddy.exe'
$Stamp=(Get-Date).ToUniversalTime().ToString('yyyyMMddHHmmss')
$Backup='C:\ProgramData\HeartOfTheRain\Review128Backup\'+$Stamp
$Public='https://api.novamind-it.ru'
function Sha([string]$Path){(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
function Up([string]$Url){try{(Invoke-WebRequest -Uri $Url -UseBasicParsing -TimeoutSec 8).StatusCode -eq 200}catch{$false}}
function WaitUp([string]$Url,[int]$Seconds){$end=(Get-Date).AddSeconds($Seconds);while((Get-Date) -lt $end){if(Up $Url){return $true};Start-Sleep -Seconds 2};return $false}
function Caddy([string]$Command,[string]$Config){
    $process=Start-Process -FilePath $CaddyExe -ArgumentList @($Command,'--config',('"'+$Config+'"'),'--adapter','caddyfile') -WindowStyle Hidden -Wait -PassThru
    return $process.ExitCode
}
$principal=New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
if(-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Run this in an elevated PowerShell.'}
foreach($path in @($Source,$Python,$Manifest,$CaddyFile,$CaddyExe)){if(-not (Test-Path -LiteralPath $path)){throw 'Missing: '+$path}}
foreach($service in 'HOTRStaging','HOTRCaddy'){if((Get-Service $service).Status -ne 'Running'){throw $service+' is not running'}}
if(-not (Up 'http://127.0.0.1:8751/readyz')){throw 'The API is not ready before deployment.'}
$pending=@()
foreach($file in $files){
    $current=Sha (Join-Path $Source $file.name)
    if($current -eq $file.new){continue}
    if($current -ne $file.old){throw 'Unexpected live version of '+$file.name+': '+$current}
    $pending+=$file
}
$text=[IO.File]::ReadAllText($CaddyFile)
$nl=if($text.Contains("`r`n")){"`r`n"}else{"`n"}
$caddyDone=$text.Contains('X-Hotr-Verified-Client-IP')
$site='api.novamind-it.ru {'
$proxy=[regex]::new('(?m)^([ \t]*)reverse_proxy 127\.0\.0\.1:8751[ \t]*\r?$')
if(-not $caddyDone){
    if(([regex]::Matches($text,[regex]::Escape($site))).Count -ne 1){throw 'Expected one site block in the Caddyfile.'}
    if($proxy.Matches($text).Count -ne 1){throw 'Expected one plain reverse_proxy line in the Caddyfile.'}
}
Write-Output ("Preflight OK. Backend files to change: {0} of {1}. Caddy already updated: {2}" -f $pending.Count,$files.Count,$caddyDone)
if($Check){Write-Output 'Check only: nothing was changed.';return}

New-Item -ItemType Directory -Force -Path $Backup | Out-Null
Copy-Item -LiteralPath $CaddyFile -Destination (Join-Path $Backup 'Caddyfile')
foreach($file in $files){Copy-Item -LiteralPath (Join-Path $Source $file.name) -Destination (Join-Path $Backup $file.name)}
Push-Location $Backend
try{
    & $Python -B -m hotr_backend.staging_sdk_ops126 backup --manifest $Manifest --name ('before-review128-'+$Stamp)
    if($LASTEXITCODE -ne 0){throw 'Online database backup failed; nothing was changed.'}
}finally{Pop-Location}

if(-not $caddyDone){
    $log=@('    # Review 128: status and duration only. The query string is removed because the VK',
           '    # callback carries OAuth values. Request bodies and credentials are not logged.',
           '    log {',
           '        output file C:/ProgramData/HeartOfTheRain/services/logs/caddy-access.log {',
           '            roll_size 10MiB',
           '            roll_keep 5',
           '            roll_keep_for 168h',
           '        }',
           '        format filter {',
           '            fields {',
           '                request>uri regexp "\?.*$" ""',
           '                request>headers delete',
           '                resp_headers delete',
           '            }',
           '            wrap json',
           '        }',
           '    }') -join $nl
    $block=$proxy.Replace($text,{param($m)$i=$m.Groups[1].Value;@(($i+'reverse_proxy 127.0.0.1:8751 {'),($i+'    # Overwrite, never append or copy an incoming identity header.'),($i+'    header_up X-Hotr-Verified-Client-IP {remote_host}'),($i+'    header_up -Forwarded'),($i+'    header_up -X-Forwarded-For'),($i+'    header_up -X-Real-IP'),($i+'}')) -join $nl},1)
    $next=$block.Replace($site,$site+$nl+$log)
    $candidate=Join-Path $Backup 'Caddyfile.candidate'
    [IO.File]::WriteAllText($candidate,$next,(New-Object Text.UTF8Encoding($false)))
    if((Caddy 'validate' $candidate) -ne 0){throw 'The new Caddy configuration did not validate; nothing was changed.'}
    # Caddy prints format warnings to stderr, which Windows PowerShell makes fatal under Stop.
    # Only its exit code and the parsed config decide this step.
    $ErrorActionPreference='Continue'
    try{$adapted=(& $CaddyExe adapt --config $candidate --adapter caddyfile 2>$null) -join ''}finally{$ErrorActionPreference='Stop'}
    if($LASTEXITCODE -ne 0 -or $adapted -notmatch 'X-Hotr-Verified-Client-IP' -or $adapted -notmatch 'caddy-access\.log'){throw 'The parsed Caddy configuration lacks the expected changes; nothing was changed.'}
    Copy-Item -LiteralPath $candidate -Destination $CaddyFile -Force
    $reloaded=(Caddy 'reload' $CaddyFile) -eq 0
    if(-not $reloaded -or -not (WaitUp ($Public+'/readyz') 40)){
        Copy-Item -LiteralPath (Join-Path $Backup 'Caddyfile') -Destination $CaddyFile -Force
        Caddy 'reload' $CaddyFile | Out-Null
        throw 'Caddy did not come back healthy; the previous config was restored.'
    }
    Write-Output 'Caddy updated and healthy.'
}

if($pending.Count -gt 0){
    foreach($file in $pending){
        $bytes=[Convert]::FromBase64String($file.data)
        $temporary=Join-Path $Backup ($file.name+'.new')
        [IO.File]::WriteAllBytes($temporary,$bytes)
        if((Sha $temporary) -ne $file.new){throw 'Embedded file failed its hash check: '+$file.name}
    }
    $restore={
        foreach($file in $files){Copy-Item -LiteralPath (Join-Path $Backup $file.name) -Destination (Join-Path $Source $file.name) -Force}
        Restart-Service HOTRStaging
        if(WaitUp 'http://127.0.0.1:8751/readyz' 120){Write-Output 'Previous backend restored and healthy.'}else{Write-Output 'WARNING: previous backend restored but not yet healthy. Check the HOTRStaging service.'}
    }
    Stop-Service HOTRStaging
    foreach($file in $pending){Copy-Item -LiteralPath (Join-Path $Backup ($file.name+'.new')) -Destination (Join-Path $Source $file.name) -Force}
    Start-Service HOTRStaging
    if(-not (WaitUp 'http://127.0.0.1:8751/readyz' 120) -or -not (WaitUp ($Public+'/readyz') 30)){
        & $restore
        throw 'The new backend did not become ready; the previous files were restored.'
    }
    Write-Output 'Backend updated and healthy.'
}
Write-Output ('Done. Backup: '+$Backup)
Get-Service HOTRStaging,HOTRCaddy | Format-Table Name,Status
foreach($route in '/healthz','/readyz'){Write-Output ($route+': '+(Invoke-WebRequest -Uri ($Public+$route) -UseBasicParsing -TimeoutSec 15).Content)}
